import { useState, useEffect } from "react";

function PostList({ selectedPost, onSelectPost, reload, categoryId }) {
    const [posts, setPosts] = useState([]);

    useEffect(() => {
        const fetchPosts = () => {
            const url = `http://localhost:5000/api/posts${categoryId ? `?category_id=${categoryId}` : ''}`;
            fetch(url)
                .then(res => res.json())
                .then(data => setPosts(data))
                .catch(err => console.error(err));
        };
        fetchPosts();
    }, [reload, categoryId]);

    if (posts.length === 0) return <p className="text-gray-500 text-center py-8">Пости відсутні</p>;

    return (
        <ul className="space-y-4">
            {posts.map(post => (
                <li key={post.id} onClick={() => onSelectPost(post.id)} className={`card-gradient p-4 rounded-xl cursor-pointer transition ${selectedPost === post.id ? "ring-4 ring-primary-400" : ""}`}>
                    <h4 className="font-bold">{post.title}</h4>
                    <p className="text-gray-600 line-clamp-2">{post.content}</p>
                </li>
            ))}
        </ul>
    );
}

export default PostList;
